      if (i <= 14) { ag += g / 14; al += l / 14; if (i === 14) out[i] = al === 0 ? 100 : 100 - 100 / (1 + ag / al); }
      else { ag = (ag * 13 + g) / 14; al = (al * 13 + l) / 14; out[i] = al === 0 ? 100 : 100 - 100 / (1 + ag / al); }
